  window.pageLine = function (key) {
    var code = (window.LANG && window.LANG.code) || "zh-CN";
    var row = PAGE[code];
    if (!row || row[key] == null || row[key] === "") return "";
    return String(row[key]);
  };
  window.pageMsg = function (raw) {
    var text = raw == null ? "" : String(raw);
    var key = SERVER[text];
    if (!key) return text;
    var line = window.pageLine(key);
    return line || text;
  };
  window.pageName = function (row) {
    var fallback = row && row.product_name ? String(row.product_name) : "";
    if (row && row.product_id && window.langName) return window.langName("product", row.product_id, fallback);
    return fallback;
  };
  window.paintKeys = function () {
    Array.prototype.forEach.call(document.querySelectorAll("[data-k]"), function (el) {
      el.textContent = window.pageLine(el.getAttribute("data-k"));
    });
    Array.prototype.forEach.call(document.querySelectorAll("[data-ph]"), function (el) {
      el.placeholder = window.pageLine(el.getAttribute("data-ph"));
    });
  };
